head.script:
scwin.screenId = "jldfil16404";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "c_when_50_txt", fn: function(){ return ((dma_educationList.get("disclsEduEvtAttendYn") ?? (() => { throw new Error("unresolved:" + "educationList.disclsEduEvtAttendYn"); })()) === 'Y'); } }, { id: "c_when_51_txt", fn: function(){ return ((dma_educationList.get("disclsEduEvtAttendYn") ?? (() => { throw new Error("unresolved:" + "educationList.disclsEduEvtAttendYn"); })()) === 'N'); } }, { id: "c_otherwise_52", fn: function(){ return (!(((dma_educationList.get("disclsEduEvtAttendYn") ?? (() => { throw new Error("unresolved:" + "educationList.disclsEduEvtAttendYn"); })()) === 'Y') || ((dma_educationList.get("disclsEduEvtAttendYn") ?? (() => { throw new Error("unresolved:" + "educationList.disclsEduEvtAttendYn"); })()) === 'N'))); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("comNm")))); } },
        { childId: "__rb1", fn: function () { return String((String(String(dma_eduDisclsChrg.get("bzRegNo")) == null ? '' : String(dma_eduDisclsChrg.get("bzRegNo"))).replace(/[^0-9]/g,'').length === 10 ? String(String(dma_eduDisclsChrg.get("bzRegNo"))).replace(/[^0-9]/g,'').slice(0,3) + '-' + String(String(dma_eduDisclsChrg.get("bzRegNo"))).replace(/[^0-9]/g,'').slice(3,5) + '-' + String(String(dma_eduDisclsChrg.get("bzRegNo"))).replace(/[^0-9]/g,'').slice(5) : String(String(dma_eduDisclsChrg.get("bzRegNo")) == null ? '' : String(dma_eduDisclsChrg.get("bzRegNo"))).replace(/[^0-9]/g,''))); } },
        { childId: "__rb3", fn: function () { return String(dma_educationList.get("eduPartcCnt")) + " 명"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_eduForm = { action: "", method: 'post', target: '' };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_conds();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil16404.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_history_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_history_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_history_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        history.back()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16404.btn_history_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_Delete_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_Delete_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_Delete_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.deleteRegisterReq('' + dma_educationList.get("disclsEduApplSeq") + '','' + dma_educationList.get("disclsChrgSeq") + '')
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16404.btn_Delete_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_Register
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Register = async function () {
    const sbmOptions = {
        id: "tx_fn_Register",
        method: "post",
        action: "/support/eduChrg.do",
        ref: "dma_RegisterReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil16404.tx_fn_Register" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
