 * @hidden N
*/
scwin.tx_fn_Delete = async function () {
    const sbmOptions = {
        id: "tx_fn_Delete",
        method: "post",
        action: "/support/eduChrg.do",
        ref: "dma_DeleteReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
