    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.reset
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.reset = function () {
    /* sdd-asis-lifecycle:begin fn_Reset — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.eduForm || { elements: [] });
    frm.reset();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.print
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.print = function () {
    /* sdd-asis-lifecycle:begin fn_Print — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.popupPrint();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.register
 * @author Inswave
 * @date 2026. 09. 29
 * @param _submitYn
 * @returns
 * @hidden N
*/
scwin.register = async function (_submitYn) {
    /* sdd-asis-lifecycle:begin fn_Register — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.eduForm || { elements: [] });
    if (!await scwin.chk()) {
        return;
    }
    frm.action = 'eduChrg.do';
    $c.util.getComponent('dma_RegisterReq').set('submitYn', _submitYn);
    $c.util.getComponent('dma_RegisterReq').set('method', 'registerChargeEducation');
    await scwin.tx_fn_Register();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.modify
 * @author Inswave
 * @date 2026. 09. 29
 * @param _submitYn
 * @returns
 * @hidden N
*/
scwin.modify = async function (_submitYn) {
    /* sdd-asis-lifecycle:begin fn_Modify — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!await scwin.chk()) {
        return;
    }
    const frm = (document.eduForm || { elements: [] });
    frm.action = 'eduChrg.do';
    $c.util.getComponent('dma_RegisterReq').set('submitYn', _submitYn);
    $c.util.getComponent('dma_RegisterReq').set('method', 'modifyChrgEducation');
    await scwin.tx_fn_Modify();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.deleteRegisterReq
 * @author Inswave
 * @date 2026. 09. 29
 * @param _disclsEduApplSeq _disclsChrgSeq _submitYn
 * @returns
 * @hidden N
*/
scwin.deleteRegisterReq = async function (_disclsEduApplSeq, _disclsChrgSeq, _submitYn) {
    /* sdd-asis-lifecycle:begin fn_Delete — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (await $c.win.confirm("삭제 하시겠습니까?") === true) {
        const eduForm = (document.eduForm || { elements: [] });
        $c.util.getComponent('dma_RegisterReq').set('disclsEduApplSeq', _disclsEduApplSeq);
        $c.util.getComponent('dma_RegisterReq').set('disclsChrgSeq', _disclsChrgSeq);
        $c.util.getComponent('dma_RegisterReq').set('submitYn', _submitYn);
        scwin.form_eduForm.action = 'eduChrg.do';
        $c.util.getComponent('dma_RegisterReq').set('method', 'removeChargeEducation');
        await scwin.tx_fn_Delete();
    } else {
        return;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.chk
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.chk = async function () {
    /* sdd-asis-lifecycle:begin fn_Chk — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.eduForm || { elements: [] });
    if (frm.chrgNm.value === "" || frm.chrgNm.value.indexOf(" ") === "") {
        await $c.win.alert("성명을 입력해 주세요");
        chrgNm.focus();
        return false;
    }
    if (frm.jobtitlNm.value === "" || frm.jobtitlNm.value.indexOf(" ") === "") {
        await $c.win.alert("직위를 입력해 주세요");
        jobtitlNm.focus();
        return false;
    }
    if (frm.cellphoneNo.value === "" || frm.cellphoneNo.value.indexOf(" ") === "") {
        await $c.win.alert("휴대폰 번호를 입력해 주세요");
        cellphoneNo.focus();
        return false;
    }
    if (frm.email.value === "" || frm.email.value.indexOf(" ") === "") {
        await $c.win.alert("이메일을 입력해 주세요");
        email.focus();
        return false;
    }
    if ((String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "disableYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("disableYn"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "disableYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("disableYn")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "disableYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("disableYn"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "disableYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("disableYn"))))) === 'Y') {
        if (frm.disclsEduEvtAttendYn.value === "") {
            await $c.win.alert("간담회 참석여부를 선택해주세요.");
            disclsEduEvtAttendYn.focus();
            return false;
        }
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.changeDest
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.changeDest = async function (obj) {
    /* sdd-asis-lifecycle:begin changeDest — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const depTpCd = obj.value;
    if (depTpCd != null && depTpCd === "01") {
        await $c.win.alert("이 기간 강의는 마감되었습니다. 다른 기간의 강의를 수강해주세요.");
        return;
    } else {
        if (depTpCd != null && depTpCd === "02") {
            (document.eduForm || { elements: [] }).tmpdestTpCd.value = "사이버교육";
            $c.util.getComponent("dma_RegisterReq").set("destTpCd", "02");
        } else {
            if (depTpCd != null && depTpCd === "03") {
                (document.eduForm || { elements: [] }).tmpdestTpCd.value = "사이버교육";
                $c.util.getComponent("dma_RegisterReq").set("destTpCd", "03");
            } else {
                (document.eduForm || { elements: [] }).tmpdestTpCd.value = "";
                $c.util.getComponent("dma_RegisterReq").set("destTpCd", "");
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};
